// 1. Zostawiamy nasz endpoint API (odbiera błędy z n8n)
add_action('rest_api_init', function () {
    register_rest_route('v1/n8n-config', '/log-error', [
        'methods' => 'POST',
        'callback' => 'save_n8n_error_log',
        'permission_callback' => 'validate_n8n_token'
    ]);
});

function save_n8n_error_log($request) {
    $params = $request->get_json_params();

    $workflow_name = sanitize_text_field($params['workflow_name'] ?? 'Nieznany potok');
    $node_name     = sanitize_text_field($params['node_name'] ?? 'Nieznany węzeł');
    $error_message = sanitize_textarea_field($params['error_message'] ?? 'Brak komunikatu błędu');

    $logs = get_option('n8n_error_logs', []);

    $new_log = [
        'time' => current_time('mysql'),
        'workflow' => $workflow_name,
        'node' => $node_name,
        'error' => $error_message
    ];

    array_unshift($logs, $new_log);
    $logs = array_slice($logs, 0, 5); // Trzymamy tylko 5 ostatnich, żeby nie robić spamu

    update_option('n8n_error_logs', $logs);

    return new WP_REST_Response(['status' => 'success'], 200);
}

// 2. NOWOŚĆ: Wyświetlanie błędu jako komunikat w kokpicie!
add_action('admin_notices', 'render_n8n_error_notices');

function render_n8n_error_notices() {
    // Pobieramy logi z bazy
    $logs = get_option('n8n_error_logs', []);

    // Jeśli nie ma błędów, nic nie wyświetlamy
    if (empty($logs)) {
        return;
    }

    // Bierzemy najnowszy błąd
    $latest_error = $logs[0];

    // Tworzymy link, który pozwoli wyczyścić błąd (żeby zniknął po przeczytaniu)
    $clear_url = wp_nonce_url(admin_url('admin-post.php?action=clear_n8n_errors'), 'clear_n8n_errors_nonce');

    ?>
    <div class="notice notice-error is-dismissible" style="border-left-color: #d63638; padding: 12px; margin-top: 20px;">
        <p style="margin: 0 0 5px 0; font-size: 14px; font-weight: bold; color: #d63638;">
            Wykryto krytyczny błąd w automatyzacji AI (n8n)!
        </p>
        <p style="margin: 0 0 8px 0;">
            <strong>Potok:</strong> <?php echo esc_html($latest_error['workflow']); ?> | 
            <strong>Nod:</strong> <code style="background: #f0f0f1; padding: 3px 6px; font-size: 12px;"><?php echo esc_html($latest_error['node']); ?></code> | 
            <strong>Czas:</strong> <?php echo esc_html($latest_error['time']); ?>
        </p>
        <p style="background: #fafafa; border-left: 4px solid #d63638; padding: 8px; margin: 5px 0 10px 0; font-family: monospace; font-size: 13px; color: #50575e;">
            <strong>Powód:</strong> <?php echo esc_html($latest_error['error']); ?>
        </p>
        <p style="margin: 0;">
            <a href="<?php echo esc_url($clear_url); ?>" class="button button-secondary button-small">Oznacz błąd jako rozwiązany / Usuń alert</a>
        </p>
    </div>
    <?php
}

// 3. Obsługa przycisku "Usuń alert"
add_action('admin_post_clear_n8n_errors', 'handle_clear_n8n_errors');

function handle_clear_n8n_errors() {
    if (!isset($_GET['_wpnonce']) || !wp_verify_nonce($_GET['_wpnonce'], 'clear_n8n_errors_nonce')) {
        wp_die('Błąd weryfikacji bezpieczeństwa.');
    }

    // Czyścimy logi z opcji bazy danych
    delete_option('n8n_error_logs');

    // Wracamy na stronę, z której przyszliśmy
    wp_redirect(wp_get_referer());
    exit;
}
